"use strict";(self.webpackChunkcoursesmith_site=self.webpackChunkcoursesmith_site||[]).push([["4303"],{8975(e,t,n){n.r(t),n.d(t,{metadata:()=>s,default:()=>d,frontMatter:()=>a,contentTitle:()=>o,toc:()=>l,assets:()=>h});var s=JSON.parse('{"id":"m3-serving-engines/deep-dive","title":"Deep Dive: PagedAttention, the Batching Scheduler & the arm64 Crash","description":"The lesson taught continuous batching, PagedAttention, and prefix caching as concepts, and the lab let you watch a queue form and a cache hit. This page goes under each of those. You will see how PagedAttention\'s block tables actually lay out memory and kill the fragmentation that caps a naive engine. You will walk the continuous-batching scheduler loop step by step, so \\"requests join and leave per step\\" becomes a mechanism you could describe to a colleague, not a slogan. Then the part most practitioners never see until it bites them in production: a forensic read of why the vLLM CPU image boots and then crashes on the Apple-Silicon path this course targets \u2014 the M1 KV math surfacing as a real error, a container-file-mount trap that eats hours, and the honest lesson that \\"the image exists for my architecture\\" is not \\"the image works on my host.\\" You close by reading prefix caching as hard evidence, not a claim. These are the layers you reach for when a serving pod OOM-kills at a concurrency you thought was safe, when an engine will not start on a new architecture, or when someone asks why one GPU serves ten times the users it \\"should.\\"","source":"@site/docs/m3-serving-engines/deep-dive.md","sourceDirName":"m3-serving-engines","slug":"/m3-serving-engines/deep-dive","permalink":"/305-llmops/docs/m3-serving-engines/deep-dive","draft":false,"unlisted":false,"tags":[],"version":"current","sidebarPosition":4,"frontMatter":{"sidebar_position":4,"title":"Deep Dive: PagedAttention, the Batching Scheduler & the arm64 Crash","sidebar_label":"Deep Dive (Part 2)"},"sidebar":"courseSidebar","previous":{"title":"Quiz: Serving Engines \u2014 Ollama, llama.cpp & vLLM","permalink":"/305-llmops/docs/m3-serving-engines/quiz"},"next":{"title":"Lesson: Embeddings, Vector Databases & RAG","permalink":"/305-llmops/docs/m4-rag-vector-db/lesson"}}'),i=n(4848),r=n(8453);let a={sidebar_position:4,title:"Deep Dive: PagedAttention, the Batching Scheduler & the arm64 Crash",sidebar_label:"Deep Dive (Part 2)"},o="Deep Dive \u2014 PagedAttention, the Batching Scheduler & the arm64 Crash",h={},l=[{value:"1 \u2014 PagedAttention: block tables and the fragmentation it kills",id:"1--pagedattention-block-tables-and-the-fragmentation-it-kills",level:2},{value:"2 \u2014 The continuous-batching scheduler, one step at a time",id:"2--the-continuous-batching-scheduler-one-step-at-a-time",level:2},{value:"3 \u2014 The arm64 crash story: what &quot;the image exists&quot; does not tell you",id:"3--the-arm64-crash-story-what-the-image-exists-does-not-tell-you",level:2},{value:"4 \u2014 Prefix caching as evidence, not a claim",id:"4--prefix-caching-as-evidence-not-a-claim",level:2},{value:"Teardown",id:"teardown",level:2}];function c(e){let t={admonition:"admonition",code:"code",em:"em",h1:"h1",h2:"h2",header:"header",li:"li",mermaid:"mermaid",p:"p",pre:"pre",strong:"strong",table:"table",tbody:"tbody",td:"td",th:"th",thead:"thead",tr:"tr",ul:"ul",...(0,r.R)(),...e.components};return(0,i.jsxs)(i.Fragment,{children:[(0,i.jsx)(t.header,{children:(0,i.jsx)(t.h1,{id:"deep-dive--pagedattention-the-batching-scheduler--the-arm64-crash",children:"Deep Dive \u2014 PagedAttention, the Batching Scheduler & the arm64 Crash"})}),"\n",(0,i.jsxs)(t.p,{children:['The lesson taught continuous batching, PagedAttention, and prefix caching as concepts, and the lab let you watch a queue form and a cache hit. This page goes under each of those. You will see how PagedAttention\'s block tables actually lay out memory and kill the fragmentation that caps a naive engine. You will walk the continuous-batching scheduler loop step by step, so "requests join and leave per step" becomes a mechanism you could describe to a colleague, not a slogan. Then the part most practitioners never see until it bites them in production: a forensic read of ',(0,i.jsx)(t.em,{children:"why"}),' the vLLM CPU image boots and then crashes on the Apple-Silicon path this course targets \u2014 the M1 KV math surfacing as a real error, a container-file-mount trap that eats hours, and the honest lesson that "the image exists for my architecture" is not "the image works on my host." You close by reading prefix caching as hard evidence, not a claim. These are the layers you reach for when a serving pod OOM-kills at a concurrency you thought was safe, when an engine will not start on a new architecture, or when someone asks why one GPU serves ten times the users it "should."']}),"\n",(0,i.jsx)(t.admonition,{title:"Where this picks up",type:"info",children:(0,i.jsxs)(t.p,{children:["You need the lab's setup: the OpsMate stack up (",(0,i.jsx)(t.code,{children:"make -C labs/opsmate up"}),") so ",(0,i.jsx)(t.code,{children:"llama-server"})," is answering on 8080, and the GGUF model present. The vLLM section is a ",(0,i.jsx)(t.em,{children:"read"}),", not a run \u2014 the crash it dissects is one you do not want to reproduce on an 8 GB laptop, and the evidence is folded in from the course spike. Nothing here changes persistent state; re-running the llama-server commands is safe."]})}),"\n",(0,i.jsx)(t.h2,{id:"1--pagedattention-block-tables-and-the-fragmentation-it-kills",children:"1 \u2014 PagedAttention: block tables and the fragmentation it kills"}),"\n",(0,i.jsxs)(t.p,{children:["The lesson's analogy was cubbies plus an index card. Here is the real mechanism. A request's KV cache is not stored as one contiguous block. It is stored as a set of fixed-size ",(0,i.jsx)(t.strong,{children:"blocks"})," (vLLM's default is 16 tokens per block), scattered across GPU memory wherever there is room, and each request carries a ",(0,i.jsx)(t.strong,{children:"block table"})," \u2014 an array mapping its logical token positions to the physical blocks that hold them."]}),"\n",(0,i.jsxs)(t.p,{children:["Walk one request. It starts with a 40-token prompt. At 16 tokens per block that needs three blocks (16 + 16 + 8, the third block half-used). The engine allocates physical blocks \u2014 say 12, 5, and 27, wherever they happen to be free \u2014 and writes the request's block table: ",(0,i.jsx)(t.code,{children:"[12, 5, 27]"}),". As decode adds tokens, block 27 fills, and the engine grabs one more free block (say 3) and appends it: ",(0,i.jsx)(t.code,{children:"[12, 5, 27, 3]"}),". The request never reserved space for tokens it had not generated. When the request finishes, all four blocks return to the free pool individually, ready for any other request."]}),"\n",(0,i.jsx)(t.mermaid,{value:'flowchart TB\n  subgraph LOGICAL["request\'s logical tokens"]\n    T["tok 0..15 | 16..31 | 32..47 | 48..63"]\n  end\n  subgraph TABLE["block table (per request)"]\n    BT["[ 12 , 5 , 27 , 3 ]"]\n  end\n  subgraph PHYS["physical KV blocks (shared pool, 16 tok each)"]\n    P12["blk 12"]\n    P5["blk 5"]\n    P27["blk 27"]\n    P3["blk 3"]\n    PF["... free blocks, reusable by anyone ..."]\n  end\n  T --\x3e BT\n  BT --\x3e P12 & P5 & P27 & P3'}),"\n",(0,i.jsxs)(t.p,{children:["Now the fragmentation math, because it is the number that justifies the whole scheme. Take the contiguous approach the paged one replaces. There, each request reserves a single block sized to the model's ",(0,i.jsx)(t.em,{children:"maximum"})," sequence length, because the memory must be contiguous and you cannot know in advance how long the request will run. Two kinds of waste follow:"]}),"\n",(0,i.jsxs)(t.ul,{children:["\n",(0,i.jsxs)(t.li,{children:[(0,i.jsx)(t.strong,{children:"Internal waste (over-reservation)."})," A request that reserves room for 2048 tokens but generates 100 leaves ~95% of its reservation unused for its whole lifetime \u2014 memory no other request can touch. Across many short requests, the majority of KV memory is reserved-but-empty."]}),"\n",(0,i.jsxs)(t.li,{children:[(0,i.jsx)(t.strong,{children:"External waste (fragmentation)."})," As requests of different sizes come and go, the free memory left between live contiguous blocks ends up in pieces too small for the next request's full reservation. The memory exists, but it is unusable \u2014 the classic fragmentation an OS solves with paging."]}),"\n"]}),"\n",(0,i.jsxs)(t.p,{children:["Paging removes both. Blocks are allocated on demand (no over-reservation \u2014 you hold exactly the blocks your tokens fill, \xb1one partial block) and any free block fits any request (no external fragmentation \u2014 a 16-token block is interchangeable). vLLM's own measurement of the effect is the headline number: near-zero KV waste against roughly 60\u201380% waste in the naive scheme, which translates directly into ",(0,i.jsx)(t.strong,{children:"several times more concurrent requests per GPU."})," That multiple ",(0,i.jsx)(t.em,{children:"is"})," throughput, and throughput is cost per answer. This is why PagedAttention was the change that made high-concurrency LLM serving economical, and why every serious engine now does something like it."]}),"\n",(0,i.jsx)(t.admonition,{title:"The one-line version to carry into a capacity review",type:"note",children:(0,i.jsx)(t.p,{children:'Contiguous KV wastes memory to over-reservation and fragmentation; paged KV holds only the blocks your tokens actually fill and lets any free block serve any request. The payoff is measured in concurrent requests per GPU \u2014 which is throughput, which is cost. When you size a serving box, the relevant number is not "how big is the model" but "how many concurrent KV blocks fit after the weights," and paging is what makes that number large.'})}),"\n",(0,i.jsx)(t.h2,{id:"2--the-continuous-batching-scheduler-one-step-at-a-time",children:"2 \u2014 The continuous-batching scheduler, one step at a time"}),"\n",(0,i.jsx)(t.p,{children:"The lesson said requests join and leave the batch every step. Here is the loop that does it. A continuous-batching engine runs a scheduler that, on every single decode step, does four things:"}),"\n",(0,i.jsx)(t.mermaid,{value:'flowchart LR\n  A["1. admit<br/>waiting requests that fit<br/>(free KV blocks?) join the batch"] --\x3e B["2. step<br/>run ONE decode step for<br/>every request in the batch, together"]\n  B --\x3e C["3. retire<br/>requests that emitted a stop token<br/>or hit max_tokens leave; free their blocks"]\n  C --\x3e D["4. preempt (if needed)<br/>no free blocks for a growing request?<br/>evict a victim\'s blocks, requeue it"]\n  D --\x3e A'}),"\n",(0,i.jsx)(t.p,{children:"Read each stage against what you saw in the lab:"}),"\n",(0,i.jsxs)(t.ul,{children:["\n",(0,i.jsxs)(t.li,{children:[(0,i.jsx)(t.strong,{children:"Admit."})," New arrivals in the waiting queue join the running batch ",(0,i.jsx)(t.em,{children:"if"})," there are free KV blocks to hold their prompt. This is where ",(0,i.jsx)(t.code,{children:"requests_deferred"})," comes from: when there is no room, arrivals wait here. The gauge you watched climb in Step 5 is the depth of this queue."]}),"\n",(0,i.jsxs)(t.li,{children:[(0,i.jsx)(t.strong,{children:"Step."})," The engine runs exactly one decode step \u2014 one token \u2014 for ",(0,i.jsx)(t.em,{children:"every"})," request in the batch at once, as a single batched matrix operation. This is the efficiency: the GPU (or CPU) does one big step covering all active requests, not one small step per request in turn."]}),"\n",(0,i.jsxs)(t.li,{children:[(0,i.jsx)(t.strong,{children:"Retire."})," Any request that just produced its stop token, or hit its ",(0,i.jsx)(t.code,{children:"max_tokens"}),", is done. It leaves the batch immediately and its KV blocks return to the pool \u2014 it does not wait for its batch-mates. This is why a short request trapped behind a long one under ",(0,i.jsx)(t.em,{children:"static"})," batching finishes on time under ",(0,i.jsx)(t.em,{children:"continuous"})," batching."]}),"\n",(0,i.jsxs)(t.li,{children:[(0,i.jsx)(t.strong,{children:"Preempt."})," The hard case: a running request needs another KV block to keep going and there are none free. The scheduler picks a victim, evicts its blocks (recomputing or swapping them later), and requeues it. This is graceful degradation under memory pressure rather than an out-of-memory crash \u2014 and it is why a well-behaved engine slows down instead of falling over when you overload it."]}),"\n"]}),"\n",(0,i.jsxs)(t.p,{children:['The property that makes this work is the one from the lesson: because the server holds no session state (M2\'s statelessness), a request is just "a block table plus a position," and adding or removing one from the batch each step is cheap. Now connect it to the numbers you measured. In Step 5 throughput climbed then flattened while p95 grew. The climb was the ',(0,i.jsx)(t.em,{children:"step"})," stage getting more efficient \u2014 more requests sharing each batched step. The flattening was the ",(0,i.jsx)(t.em,{children:"admit"})," stage stalling \u2014 no free blocks, arrivals deferred. And on a CPU that ceiling is low because each step is slow; on a GPU with PagedAttention it is high because steps are fast ",(0,i.jsx)(t.em,{children:"and"})," far more requests fit in memory. Same scheduler, different ceiling \u2014 which is exactly the argument for vLLM-on-GPU in production and llama-server for portable CPU serving."]}),"\n",(0,i.jsxs)(t.p,{children:["You can watch the ",(0,i.jsx)(t.em,{children:"retire"})," and ",(0,i.jsx)(t.em,{children:"admit"})," stages breathe on your own engine. Fire a burst and sample the in-flight and deferred gauges tightly:"]}),"\n",(0,i.jsx)(t.pre,{children:(0,i.jsx)(t.code,{className:"language-bash",children:'( for i in $(seq 1 20); do\n    curl -s http://localhost:8080/v1/chat/completions \\\n      -H "Content-Type: application/json" \\\n      -d \'{"model":"qwen3-0.6b","max_tokens":64,"messages":[{"role":"user","content":"Count slowly to twenty."}]}\' \\\n      >/dev/null & done; wait ) &\nfor n in $(seq 1 8); do\n  curl -s http://localhost:8080/metrics \\\n    | awk \'/requests_processing / && !/HELP/ {p=$2} /requests_deferred / && !/HELP/ {d=$2} END {print "processing="p" deferred="d}\'\n  sleep 0.4\ndone\n'})}),"\n",(0,i.jsxs)(t.p,{children:[(0,i.jsx)(t.strong,{children:"Expected output"})," (point-in-time \u2014 the numbers rise then drain as requests retire)"]}),"\n",(0,i.jsx)(t.pre,{children:(0,i.jsx)(t.code,{className:"language-text",children:"processing=0 deferred=0\nprocessing=4 deferred=12\nprocessing=4 deferred=8\nprocessing=4 deferred=4\nprocessing=4 deferred=1\nprocessing=3 deferred=0\nprocessing=1 deferred=0\nprocessing=0 deferred=0\n"})}),"\n",(0,i.jsxs)(t.p,{children:["Read the drain. ",(0,i.jsx)(t.code,{children:"processing"})," pins at the batch width the engine admits; ",(0,i.jsx)(t.code,{children:"deferred"})," starts high (the burst arrived faster than the engine could admit it) and falls step by step as running requests ",(0,i.jsx)(t.em,{children:"retire"})," and free blocks let the ",(0,i.jsx)(t.em,{children:"admit"})," stage pull the next ones in. That staircase down is the scheduler loop, observed. In production this is precisely the pattern you watch: a ",(0,i.jsx)(t.code,{children:"deferred"})," that drains is a healthy engine under a spike; a ",(0,i.jsx)(t.code,{children:"deferred"})," that stays pinned is an engine that needs another replica (M9)."]}),"\n",(0,i.jsx)(t.h2,{id:"3--the-arm64-crash-story-what-the-image-exists-does-not-tell-you",children:'3 \u2014 The arm64 crash story: what "the image exists" does not tell you'}),"\n",(0,i.jsxs)(t.p,{children:["This is the section most practitioners never get taught, because it only shows up when you try to run a production GPU engine on the wrong hardware \u2014 which you will, the first time you reach for vLLM on a laptop or a cheap CPU node. This course ran that experiment so you do not have to reproduce it blind. On the Apple-Silicon 8 GB path, the ",(0,i.jsx)(t.code,{children:"vllm/vllm-openai"})," CPU image for arm64 ",(0,i.jsx)(t.strong,{children:"exists, pulls, and boots \u2014 and then crashes on the first inference."})," Five configurations were tested; reading each failure honestly is the lesson."]}),"\n",(0,i.jsxs)(t.table,{children:[(0,i.jsx)(t.thead,{children:(0,i.jsxs)(t.tr,{children:[(0,i.jsx)(t.th,{children:"Attempt"}),(0,i.jsx)(t.th,{children:"Configuration"}),(0,i.jsx)(t.th,{children:"What happened"}),(0,i.jsx)(t.th,{children:"What it teaches"})]})}),(0,i.jsxs)(t.tbody,{children:[(0,i.jsxs)(t.tr,{children:[(0,i.jsx)(t.td,{children:"1"}),(0,i.jsxs)(t.td,{children:[(0,i.jsx)(t.code,{children:"latest-arm64"}),", bf16, HF-cache mount"]}),(0,i.jsxs)(t.td,{children:[(0,i.jsx)(t.strong,{children:"Boot failed"}),' \u2014 the symlinked Hugging Face cache was unreadable through the container file mount ("Operation not permitted" resolving snapshot symlinks)']}),(0,i.jsxs)(t.td,{children:["Mount a ",(0,i.jsx)(t.em,{children:"plain"})," model directory, not an HF symlink farm"]})]}),(0,i.jsxs)(t.tr,{children:[(0,i.jsx)(t.td,{children:"2"}),(0,i.jsxs)(t.td,{children:[(0,i.jsx)(t.code,{children:"latest-arm64"}),", bf16, plain dir, 2 GiB KV"]}),(0,i.jsxs)(t.td,{children:[(0,i.jsx)(t.strong,{children:"Engine init failed"})," \u2014 honest error: less free memory than the KV cache requested after weights + compile"]}),(0,i.jsx)(t.td,{children:"The M1 KV math, surfacing as a real ops error"})]}),(0,i.jsxs)(t.tr,{children:[(0,i.jsx)(t.td,{children:"3"}),(0,i.jsxs)(t.td,{children:[(0,i.jsx)(t.code,{children:"latest-arm64"}),", bf16, 1 GiB KV"]}),(0,i.jsxs)(t.td,{children:[(0,i.jsx)(t.strong,{children:"API up, then crashed"})," \u2014 ",(0,i.jsx)(t.code,{children:"/v1/models"})," served, the first completion killed the engine worker (died inside a torch matrix op)"]}),(0,i.jsx)(t.td,{children:"A CPU-inference image being present \u2260 working on this host"})]}),(0,i.jsxs)(t.tr,{children:[(0,i.jsx)(t.td,{children:"4"}),(0,i.jsxs)(t.td,{children:[(0,i.jsx)(t.code,{children:"latest-arm64"}),", fp32, 1 GiB KV"]}),(0,i.jsxs)(t.td,{children:[(0,i.jsx)(t.strong,{children:"Hung \u226519 min"}),' in "compilation" (a starvation loop), never served']}),(0,i.jsx)(t.td,{children:"Falling back to fp32 is not a fix; it hangs harder"})]}),(0,i.jsxs)(t.tr,{children:[(0,i.jsx)(t.td,{children:"5"}),(0,i.jsxs)(t.td,{children:[(0,i.jsx)(t.code,{children:"--enforce-eager"})," ",(0,i.jsx)(t.strong,{children:"and"})," pinned ",(0,i.jsx)(t.code,{children:"v0.23.0-arm64"})]}),(0,i.jsx)(t.td,{children:(0,i.jsx)(t.strong,{children:"Same first-completion crash"})}),(0,i.jsx)(t.td,{children:"Not a version regression; the CPU path itself is broken on this host"})]})]})]}),"\n",(0,i.jsx)(t.p,{children:"Three findings carry into how you make engine decisions."}),"\n",(0,i.jsxs)(t.p,{children:[(0,i.jsx)(t.strong,{children:"Finding one \u2014 a KV-sizing error is the M1 math in the wild."})," Attempt 2 failed at engine init with a message that is worth quoting, because it is the M1/M2 memory math you have been doing by hand, now printed by a real engine refusing to start:"]}),"\n",(0,i.jsx)(t.pre,{children:(0,i.jsx)(t.code,{className:"language-text",children:"ValueError: To serve at least one request with the models's max seq len (2048),\n(2.00 GiB KV cache is needed, which is larger than the available KV cache memory\n(1.77 GiB). Based on the available memory, ... try increasing\n`gpu_memory_utilization` or decreasing `max_model_len` when initializing the engine.\n"})}),"\n",(0,i.jsxs)(t.p,{children:["Read what it is telling you. The weights loaded, the runtime buffers allocated, and ",(0,i.jsx)(t.em,{children:"then"})," the engine tried to reserve KV cache for a 2048-token context \u2014 and there was not enough left (1.77 GiB free against a 2.00 GiB request). This is exactly the three-part memory box from M2 (weights + runtime buffers + KV cache), and exactly the KV-sizing lever from M1, hitting a hard wall. The fix the engine itself suggests \u2014 decrease ",(0,i.jsx)(t.code,{children:"max_model_len"})," (shorter context, smaller KV reservation) or raise the memory it is allowed to use \u2014 is the same lever you learned to reach for. This is why the memory math is not academic: an engine that will not start prints it back at you as a ",(0,i.jsx)(t.code,{children:"ValueError"}),", and knowing the math is how you read the fix in the message."]}),"\n",(0,i.jsxs)(t.p,{children:[(0,i.jsx)(t.strong,{children:"Finding two \u2014 the HF-symlink-vs-mount gotcha, and why plain model dirs win."})," Attempt 1 never got to inference; it died on the ",(0,i.jsx)(t.em,{children:"file layout"}),". Hugging Face's cache stores model files as a farm of symlinks (a ",(0,i.jsx)(t.code,{children:"snapshots/"})," dir pointing into a ",(0,i.jsx)(t.code,{children:"blobs/"}),' store). Some container file-mount layers cannot resolve those symlinks \u2014 the mount surfaces them but refuses to follow them ("Operation not permitted") \u2014 so the engine sees dangling links instead of weights and cannot start. The fix is the one this course bakes into the lab: mount a ',(0,i.jsx)(t.strong,{children:"plain, materialised model directory"})," (real files, no symlinks), which is why ",(0,i.jsx)(t.code,{children:"labs/opsmate/models/qwen3-0.6b/"})," holds actual ",(0,i.jsx)(t.code,{children:".safetensors"})," and ",(0,i.jsx)(t.code,{children:".json"}),' files, not an HF cache. It is also better pedagogy \u2014 you can see the artefacts \u2014 and it is a habit that saves you every time a model refuses to load "for no reason" inside a container. When a containerized engine cannot find weights that are clearly right there, suspect the symlink farm first.']}),"\n",(0,i.jsxs)(t.p,{children:[(0,i.jsx)(t.strong,{children:"Finding three \u2014 presence is not viability."})," Attempts 3, 4, and 5 are the real lesson, and it is a mindset, not a command. The arm64 CPU image is ",(0,i.jsx)(t.em,{children:"real"})," \u2014 it exists in the registry, it pulls, its API comes up and serves ",(0,i.jsx)(t.code,{children:"/v1/models"}),'. Everything short of actual inference works. Then the first completion crashes the engine worker inside a low-level math kernel, and no amount of config (fp32, eager mode, an older pinned version) fixes it, because the CPU inference path itself is not viable on this VM host. The takeaway you carry into every "can we run X here?" decision: ',(0,i.jsx)(t.strong,{children:"an image being available for your architecture tells you nothing about whether it works on your host."})," You verify by running the real workload \u2014 a completion, not a health check \u2014 before you commit an architecture to it. This is why the course spikes engines on the target hardware instead of trusting the registry, and why your M3 hands-on engine is llama-server (which ",(0,i.jsx)(t.em,{children:"does"})," run everywhere this course goes) with vLLM taught fully and run where it fits."]}),"\n",(0,i.jsxs)(t.p,{children:[(0,i.jsx)(t.strong,{children:"A postscript, not a contradiction: changing the engine, not the config, is what actually worked."})," This section's lesson holds \u2014 no ",(0,i.jsx)(t.em,{children:"config"})," on the official ",(0,i.jsx)(t.code,{children:"vllm/vllm-openai"})," image fixes the arm64 crash. But a different image can, and this course now ships one: ",(0,i.jsx)(t.code,{children:"schoolofdevops/vllm-cpu-nonuma"})," patches the specific container-NUMA bug behind attempts 3\u20135 (a ",(0,i.jsx)(t.code,{children:"numa_migrate_pages"})," failure the official image never surfaces cleanly, since it dies inside a different low-level path first). Step 7 in the lab uses it, and it runs \u2014 real completions, real ",(0,i.jsx)(t.code,{children:"/metrics"})," \u2014 on this same arm64 8 GB host. It is genuinely slow (real captured number: ~2.9 seconds per output token, versus llama-server's much faster decode), and it needs ",(0,i.jsx)(t.code,{children:"--privileged"}),' to work around the NUMA syscall. That is not a rebuttal of "verify with a real completion before committing an architecture" \u2014 it is the same discipline, applied a second time, to a second candidate.']}),"\n",(0,i.jsx)(t.admonition,{title:"The forensic habit",type:"tip",children:(0,i.jsxs)(t.p,{children:["When a serving engine fails, read the failure ",(0,i.jsx)(t.em,{children:"stage"}),", not just the fact it failed. Boot failure \u2192 suspect file layout and mounts (the symlink trap). Init failure with a memory number \u2192 the KV math, and the fix is in the message (shorter context or more memory). Serves-then-crashes-on-inference \u2192 the compute path is not viable on this host; stop tuning config and change the engine or the hardware. The stage tells you which of the three findings you are looking at."]})}),"\n",(0,i.jsx)(t.h2,{id:"4--prefix-caching-as-evidence-not-a-claim",children:"4 \u2014 Prefix caching as evidence, not a claim"}),"\n",(0,i.jsxs)(t.p,{children:["The lab showed one ",(0,i.jsx)(t.code,{children:"cached_tokens"}),' hit. Here you read it as a controlled experiment, because "the cache works" is a claim, and an operator ships on evidence. The test: hold the system prompt identical and vary only the user turn, three times, and watch the cached count. If prefix caching is real, the shared system prefix should be served from cache on every call after the first, regardless of what the user asks.']}),"\n",(0,i.jsx)(t.pre,{children:(0,i.jsx)(t.code,{className:"language-bash",children:'SYS=\'You are OpsMate, an SRE assistant. Follow the runbook precisely. Cite the step number for every action. Prefer the least-disruptive fix first. /no_think\'\nfor U in "Check one: is the service listening?" "Check two: are its dependencies healthy?" "Check three: what changed recently?"; do\n  curl -s http://localhost:8080/v1/chat/completions \\\n    -H "Content-Type: application/json" \\\n    -d "$(jq -n --arg s "$SYS" --arg u "$U" \\\n        \'{model:"qwen3-0.6b", messages:[{role:"system",content:$s},{role:"user",content:$u}]}\')" \\\n    | jq -c \'{user: "\'"$U"\'"[0:18], prompt: .usage.prompt_tokens, cached: .usage.prompt_tokens_details.cached_tokens}\'\ndone\n'})}),"\n",(0,i.jsxs)(t.p,{children:[(0,i.jsx)(t.strong,{children:"Expected output"})," (cached counts are point-in-time; the pattern is the evidence)"]}),"\n",(0,i.jsx)(t.pre,{children:(0,i.jsx)(t.code,{className:"language-text",children:'{"user":"Check one: is the","prompt":54,"cached":0}\n{"user":"Check two: are its","prompt":54,"cached":41}\n{"user":"Check three: what","prompt":55,"cached":41}\n'})}),"\n",(0,i.jsxs)(t.p,{children:["Read it as the experiment it is. The first call primes the cache \u2014 nothing cached, the whole prompt prefilled. The second and third calls, with ",(0,i.jsx)(t.em,{children:"different"})," user questions but the ",(0,i.jsx)(t.em,{children:"same"})," system prefix, each report a non-zero ",(0,i.jsx)(t.code,{children:"cached"})," (41 here) \u2014 the shared system prompt served from cache while only the differing user tokens got real prefill. That is the mechanism proven: the cache keys on the ",(0,i.jsx)(t.em,{children:"prefix"}),", so it survives a changing tail. In an application where a long standing instruction fronts every request \u2014 a runbook preamble, a persona, a tool schema \u2014 this is prefill you pay for once and reuse on every subsequent call, and it is a large standing saving at scale. (Your exact cached numbers depend on the tokeniser and how the build counts partial blocks; call one may even read a small non-zero value if earlier requests in your session warmed the cache. The invariant is the ",(0,i.jsx)(t.em,{children:"jump"}),": near-zero on the first call, a large shared-prefix count on the repeats.)"]}),"\n",(0,i.jsxs)(t.p,{children:["The operational reading: prefix caching rewards you for ",(0,i.jsx)(t.em,{children:"structuring prompts prefix-stable"})," \u2014 put the fixed material (system prompt, instructions, retrieved context that repeats) at the front, the variable material (the user's specific question) at the back. A prompt that shuffles its fixed content, or puts a timestamp at the very top, defeats the cache and re-prefills everything every time. This is a real design lever you will use in M4 (where RAG prepends retrieved chunks) and M12 (where the gateway can share a cache across callers): form the prefix to be stable and the engine pays you back in prefill it skips."]}),"\n",(0,i.jsx)(t.admonition,{title:"Where you will use this",type:"tip",children:(0,i.jsxs)(t.ul,{children:["\n",(0,i.jsxs)(t.li,{children:[(0,i.jsx)(t.strong,{children:"PagedAttention makes concurrent capacity, not model size, the number that matters \u2014 size a box by KV blocks after weights."})," ",(0,i.jsx)(t.strong,{children:"Use it when:"})," a serving pod OOM-kills at a concurrency you thought was safe \u2014 the fix is fewer reserved blocks (shorter ",(0,i.jsx)(t.code,{children:"max_model_len"}),") or more memory, and paging is what lets the rest fit at all."]}),"\n",(0,i.jsxs)(t.li,{children:[(0,i.jsxs)(t.strong,{children:["The batching scheduler admits, steps, retires, and preempts every token \u2014 ",(0,i.jsx)(t.code,{children:"deferred"})," is the admit queue."]})," ",(0,i.jsx)(t.strong,{children:"Use it when:"})," you are deciding whether one replica is full \u2014 a ",(0,i.jsx)(t.code,{children:"requests_deferred"})," that drains is healthy under a spike; one that stays pinned is the signal to scale out (M9)."]}),"\n",(0,i.jsxs)(t.li,{children:[(0,i.jsx)(t.strong,{children:"An image existing for your architecture is not the image working on your host \u2014 verify with a real completion."})," ",(0,i.jsx)(t.strong,{children:"Use it when:"})," you evaluate any new engine or architecture \u2014 run inference, not just a health check, before you commit; and read the failure ",(0,i.jsx)(t.em,{children:"stage"})," (boot / init / inference) to know which problem you have."]}),"\n",(0,i.jsxs)(t.li,{children:[(0,i.jsx)(t.strong,{children:"Prefix caching rewards prefix-stable prompts \u2014 fixed material first, variable material last."})," ",(0,i.jsx)(t.strong,{children:"Use it when:"})," you design prompts that repeat a long preamble (RAG in M4, the gateway in M12) \u2014 structure the prefix to be byte-stable and the engine skips its prefill on every call after the first."]}),"\n"]})}),"\n",(0,i.jsx)(t.h2,{id:"teardown",children:"Teardown"}),"\n",(0,i.jsxs)(t.p,{children:["Nothing here seeded persistent state beyond what the lab already started. If the OpsMate stack is still up from the lab, tear it down when you are done: ",(0,i.jsx)(t.code,{children:"make -C labs/opsmate down"}),". The GGUF model file stays on disk for M4, which restarts this same stack and adds a retriever and vector database beside the engine you built here."]})]})}function d(e={}){let{wrapper:t}={...(0,r.R)(),...e.components};return t?(0,i.jsx)(t,{...e,children:(0,i.jsx)(c,{...e})}):c(e)}},8453(e,t,n){n.d(t,{R:()=>a,x:()=>o});var s=n(6540);let i={},r=s.createContext(i);function a(e){let t=s.useContext(r);return s.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function o(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(i):e.components||i:a(e.components),s.createElement(r.Provider,{value:t},e.children)}}}]);